try {
    const cb = $input.first().json.callback_query;
    if (!cb) throw new Error("Нет данных callback_query");

    const dataParts = cb.data.split('_');
    const action = dataParts[0];
    const ticketId = dataParts[1];
    const resolution = dataParts[2] || "none"; // Извлекаем резолюцию (success/vendor/spam)

    const firstName = cb.from.first_name || "";
    const username = cb.from.username ? `(@${cb.from.username})` : "";
    const engineerName = `${firstName} ${username}`.trim();

    const originalText = cb.message.text || "";

    return [{
        json: {
            action: action,
            ticket_id: ticketId,
            resolution: resolution,
            message_id: cb.message.message_id,
            chat_id: cb.message.chat.id,
            query_id: cb.id,
            engineer_id: String(cb.from.id),
            engineer_name: engineerName,
            original_text: originalText
        }
    }];
} catch (error) {
    throw new Error(`[Callback Parser Error]: ${error.message}`);
}

