const item = $input.first().json;
const repliedMsgText = item.message?.reply_to_message?.text || "";
const engineerText = item.message?.text || "";

// Ищем ID тикета после знака # (буквы, цифры или тире)
const match = repliedMsgText.match(/#([a-zA-Z0-9-]+)/);
const ticketId = match ? match[1] : null;

return {
    ticket_id: ticketId,
    engineer_text: engineerText
};

