const item = $input.first().json;
const text = item.message?.text || "";
const repliedMsgText = item.message?.reply_to_message?.text || "";

const match = repliedMsgText.match(/#([a-zA-Z0-9-]+)/);
const ticketId = match ? match[1] : null;

// Ищем блоки (добавил флаг 'i' на случай, если кто-то напишет [Инструкция] строчными)
const instructionMatch = text.match(/\[ИНСТРУКЦИЯ\]([\s\S]*?)\[ДОСТУПЫ\]/i);
const instruction = instructionMatch ? instructionMatch[1].trim() : "Инструкция не найдена.";

const credentialsMatch = text.match(/\[ДОСТУПЫ\]([\s\S]*)/i);
const credentials = credentialsMatch ? credentialsMatch[1].trim() : "Доступы не найдены.";

return [{
    json: {
        ticket_id: ticketId,
        setup_summary: instruction,             // 🌟 Изменили название ключа!
        infrastructure_accesses: credentials    // 🌟 Изменили название ключа!
    }
}];

